494. // Booking a previously-free frame at index `fnn` sets its bit and initialises its slot to 1. This
495. // preserves `internal_inv` and moves `pa` (= `fnn * ps`) from the free set to the allocated set with
496. // a refcount entry of 1. Used by `book`.
497. proof fn lemma_refcount_book(old_inner: &Inner, new_inner: &Inner, fnn: int, pa: int)
498.     requires
499.         old_inner.inv(),
500.         0 <= fnn < old_inner.bitmap@.num_bits,
501.         !old_inner.bitmap@.set_bits.contains(fnn),
502.         new_inner.refcount@ == old_inner.refcount@.update(fnn, 1),
503.         new_inner.bitmap.inv(),
504.         new_inner.bitmap@.num_bits == old_inner.bitmap@.num_bits,
505.         new_inner.bitmap@.set_bits == old_inner.bitmap@.set_bits.insert(fnn),
506.         pa == fnn * spec_page_size(),
507.     ensures
508.         new_inner.internal_inv(),
509.         new_inner@.allocated_frames =~= old_inner@.allocated_frames.insert(pa),
510.         new_inner@.free_frames =~= old_inner@.free_frames.remove(pa),
511.         new_inner@.refcounts =~= old_inner@.refcounts.insert(pa, 1int),
512. {
513.     let ps: int = spec_page_size();
514.     let nbits: int = old_inner.bitmap@.num_bits;
515.     assert(ps > 0);
516.     assert(old_inner.bitmap.inv());
517.     assert(old_inner.bitmap@.wf());
518.     assert(new_inner.refcount@.len() == old_inner.refcount@.len());
519.     assert(new_inner.refcount@[fnn] == 1);
520.     assert(pa == frame_addr_of(fnn));
521.     // The previously-free slot was zero.
522.     assert(old_inner.refcount@[fnn] == 0);
523.     assert forall|i: int| #[trigger] new_inner.bitmap@.set_bits.contains(i) <==> (
524.         old_inner.bitmap@.set_bits.contains(i) || i == fnn
525.     ) by {}
526. 
527.     // internal_inv(new_inner): only slot `fnn` changed; it is now set and equal to 1.
528.     assert(new_inner.internal_inv()) by {
529.         assert(new_inner.bitmap.inv());
530.         assert forall|i: int| 0 <= i < nbits implies (
531.             #[trigger] new_inner.bitmap@.set_bits.contains(i) <==> new_inner.refcount@[i] > 0
532.         ) by {
533.             if i == fnn {
534.             } else {
535.                 assert(new_inner.refcount@[i] == old_inner.refcount@[i]);
536.             }
537.         };
538.         assert forall|i: int| 0 <= i < nbits implies (
539.             !(#[trigger] new_inner.bitmap@.set_bits.contains(i)) <==> new_inner.refcount@[i] == 0
540.         ) by {
541.             if i == fnn {
542.             } else {
543.                 assert(new_inner.refcount@[i] == old_inner.refcount@[i]);
544.             }
545.         };
546.         assert forall|i: int| 0 <= i < nbits && new_inner.bitmap@.set_bits.contains(i) implies
547.             0 < #[trigger] new_inner.refcount@[i] <= 255 by {
548.             if i == fnn {
549.             } else {
550.                 assert(new_inner.refcount@[i] == old_inner.refcount@[i]);
551.             }
552.         };
553.         assert forall|i: int| nbits <= i < new_inner.refcount@.len() implies
554.             #[trigger] new_inner.refcount@[i] == 0 by {
555.             assert(i != fnn);
556.             assert(new_inner.refcount@[i] == old_inner.refcount@[i]);
557.         };
558.     };
559. 
560.     // allocated_frames: add `pa`.
561.     assert(new_inner@.allocated_frames =~= old_inner@.allocated_frames.insert(pa)) by {
562.         assert forall|addr: int| new_inner@.allocated_frames.contains(addr) implies
563.             #[trigger] old_inner@.allocated_frames.insert(pa).contains(addr) by {
564.             let i = choose|i: int|
565.                 #[trigger] new_inner.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
566.             assert(addr == i * ps);
567.             if i == fnn {
568.                 assert(addr == pa);
569.             } else {
570.                 assert(old_inner.bitmap@.set_bits.contains(i));
571.             }
572.         }
573.         assert forall|addr: int| old_inner@.allocated_frames.insert(pa).contains(addr) implies
574.             #[trigger] new_inner@.allocated_frames.contains(addr) by {
575.             if addr == pa {
576.                 assert(new_inner.bitmap@.set_bits.contains(fnn));
577.             } else {
578.                 let i = choose|i: int|
579.                     #[trigger] old_inner.bitmap@.set_bits.contains(i) && addr == frame_addr_of(i);
580.                 assert(addr == i * ps);
581.                 assert(new_inner.bitmap@.set_bits.contains(i));
582.             }
583.         }
584.     };
585. 
586.     // free_frames: drop `pa`.
587.     assert(new_inner@.free_frames =~= old_inner@.free_frames.remove(pa)) by {
588.         assert forall|addr: int| new_inner@.free_frames.contains(addr) implies
589.             #[trigger] old_inner@.free_frames.remove(pa).contains(addr) by {
