+            #[trigger] new_inner@.free_frames.contains(addr) by {
+            let i = choose|i: int|
+                0 <= i < nbits && !(#[trigger] old_inner.bitmap@.set_bits.contains(i))
+                    && addr == frame_addr_of(i);
+            assert(addr == i * ps);
+            if lo <= i < hi {
+                assert(fs.contains(addr));
