943.         &mut self,
944.         region: &TruncatedMemoryRegion<PhysicalAddress>,
945.     ) -> Result<(), Error> {
946.         proof! { admit(); }
947.         let start_frame_number: usize = region.start().into_frame_number().into_raw_value();
948.         let end_frame_number: usize = start_frame_number + region.size() / mem::FRAME_SIZE - 1;
949. 
950.         // Check that all frames in the range are covered by the bitmap and free,
951.         // then book them. Uncovered frames indicate a memory layout bug.
952.         //
953.         // The coverage check runs unconditionally — including optimized builds —
954.         // because out-of-bounds indices must be rejected before attempting to set them.
955.         // This loop runs only at boot when booking memory regions, so the overhead is negligible.
956.         #[cfg_attr(verus_keep_ghost, verus_spec(invariant false))]
957.         for index in start_frame_number..=end_frame_number {
958.             if index >= self.bitmap.number_of_bits() {
959.                 let uncovered_addr: usize = index * mem::FRAME_SIZE;
960.                 let reason: &str = "frame index not covered by the bitmap";
961.                 #[cfg(not(verus_keep_ghost))]
962.                 error!("{} (frame={:#010x}, region={:?})", reason, uncovered_addr, region);
963.                 return Err(Error::new(ErrorCode::InvalidArgument, reason));
964.             }
965.             match self.bitmap.test(index) {
966.                 Ok(false) => {},
967.                 Ok(true) => {
968.                     let conflicting_addr: usize = index * mem::FRAME_SIZE;
969.                     let region_start: usize = region.start().into_raw_value();
970.                     let region_end: usize = region_start.saturating_add(region.size());
971.                     let reason: &str = "frame is already allocated";
972.                     #[cfg(not(verus_keep_ghost))]
